/** Text-only opening, replayable from Settings. */
const copy={en:{title:'FieldShift',body:'Explore weather, water, soil, crop rotations and profit for the land you choose.',enter:'Enter FieldShift',replay:'Replay introduction',replayBody:'See the FieldShift introduction again.'},fr:{title:'FieldShift',body:'Explorez la météo, l’eau, le sol, les rotations et les bénéfices pour la terre choisie.',enter:'Entrer dans FieldShift',replay:'Revoir l’introduction',replayBody:'Revoir l’introduction de FieldShift.'},ar:{title:'فيلد شيفت',body:'استكشف الطقس والمياه والتربة وتناوب المحاصيل والأرباح للأرض التي تختارها.',enter:'دخول فيلد شيفت',replay:'إعادة المقدمة',replayBody:'شاهد مقدمة فيلد شيفت مرة أخرى.'}};
export function initIntro({language='en'}={}){
  let current=copy[language]?language:'en',hideTimer;
  const overlay=document.createElement('section');overlay.className='fieldshift-intro text-intro';overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.setAttribute('aria-label','FieldShift introduction');
  overlay.innerHTML='<div class="text-intro-content"><h1></h1><p></p><button type="button" class="text-intro-enter"></button></div>';document.body.append(overlay);
  const panel=document.querySelector('.settings-panel');const row=document.createElement('div');row.className='setting-item intro-replay-setting';row.innerHTML='<div><b></b><p></p></div><button type="button" class="button secondary small"></button>';panel.append(row);
  const apply=()=>{const words=copy[current];overlay.querySelector('h1').textContent=words.title;overlay.querySelector('p').textContent=words.body;overlay.querySelector('button').textContent=words.enter;row.querySelector('b').textContent=words.replay;row.querySelector('p').textContent=words.replayBody;row.querySelector('button').textContent=words.replay;};
  const close=()=>{overlay.classList.add('leaving');document.body.classList.remove('intro-open');hideTimer=setTimeout(()=>overlay.hidden=true,420);document.querySelector('.topbar-field')?.focus();};
  const open=()=>{clearTimeout(hideTimer);overlay.hidden=false;overlay.classList.remove('leaving');document.body.classList.add('intro-open');overlay.querySelector('button').focus();};
  overlay.querySelector('button').onclick=close;row.querySelector('button').onclick=open;overlay.addEventListener('keydown',event=>{if(event.key==='Escape')close();});window.addEventListener('fieldshift:language',event=>{current=copy[event.detail]?event.detail:'en';apply();});apply();if(!sessionStorage.getItem('fieldshift.intro.skip-auto'))requestAnimationFrame(open);else overlay.hidden=true;return{open};
}
